window.ANIMAUX = (window.ANIMAUX || []).concat([

{id:"loup-gris",nom:"Loup gris",sci:"Canis lupus",emo:"🐺",gr:"Mammifère",ord:"Carnivora",fam:"Canidés",bio:"foret",
hab:"Forêts, toundras, steppes",rep:"Hémisphère nord",taille:"1,1 à 1,5 m + queue",poidsKg:45,vit:60,vie:13,
reg:"Carnivore",uicn:"LC",rar:2,
res:"Ancêtre sauvage de tous les chiens domestiques. Un prédateur social dont l'organisation a été mal comprise pendant cinquante ans.",
f:[["La meute n'est pas une armée de rivaux : c'est une famille. Un couple reproducteur et ses petits des dernières années.","base"],
["Le fameux « mâle alpha » qui domine ses rivaux est une erreur scientifique. Elle vient d'observations faites sur des loups sans lien de parenté enfermés ensemble en captivité. David Mech, l'auteur du livre qui a popularisé l'idée, passe depuis des années à demander qu'on arrête de le citer.","expert"],
["Le hurlement porte jusqu'à 10 km en forêt et jusqu'à 16 km en terrain dégagé. Chaque loup a une signature vocale reconnaissable individuellement.","pointu"],
["Réintroduits à Yellowstone en 1995, les loups ont fait remonter les saules et les peupliers en repoussant les wapitis loin des berges. On appelle ça une cascade trophique — un prédateur qui redessine un paysage.","expert"]],
v:[["Cascade trophique","Effet en chaîne : un prédateur au sommet modifie le comportement de ses proies, ce qui change la végétation, ce qui change les rivières, les oiseaux, les castors…"]],
q:[["D'où vient le mythe du « mâle alpha » chez le loup ?",["D'observations de loups captifs sans lien de parenté","De l'étude des meutes sauvages du Canada","Des récits de trappeurs du XIXᵉ siècle","De l'observation des chiens errants"],0,"Des loups étrangers enfermés ensemble se battent pour le rang. Une vraie meute sauvage est une famille : les « alphas » sont juste les parents."],
["Combien de vertèbres cervicales possède un loup ?",["5","7","9","13"],1,"Sept, comme presque tous les mammifères — de la girafe à la souris."]],
d:["records"]},

{id:"ours-polaire",nom:"Ours polaire",sci:"Ursus maritimus",emo:"🐻‍❄️",gr:"Mammifère",ord:"Carnivora",fam:"Ursidés",bio:"polaire",
hab:"Banquise, côtes arctiques",rep:"Arctique circumpolaire",taille:"2 à 2,5 m",poidsKg:450,vit:40,vie:25,
reg:"Carnivore",uicn:"VU",rar:3,
res:"Le plus grand carnivore terrestre, et le seul ours classé comme mammifère marin. Sa survie est directement indexée sur la glace de mer.",
f:[["Sa peau est noire sous la fourrure. Le noir absorbe mieux la chaleur du soleil.","base"],
["Ses poils ne sont pas blancs : ils sont transparents et creux. Ils paraissent blancs parce qu'ils diffusent la lumière dans toutes les directions, exactement comme la neige ou la mousse de bière.","pointu"],
["Son foie contient tellement de vitamine A qu'en manger peut tuer un humain. Plusieurs explorateurs polaires en sont morts.","expert"],
["Il chasse à l'affût près d'un trou de respiration de phoque et peut rester immobile plus d'une heure. Sur la glace, il repère un phoque à près d'un kilomètre — à l'odeur.","base"]],
v:[["Mammifère marin","Mammifère dont la vie dépend du milieu marin. L'ours polaire y est classé car il chasse sur la banquise et nage sur des dizaines de kilomètres."]],
q:[["De quelle couleur est la peau d'un ours polaire ?",["Blanche","Rose","Noire","Grise"],2,"Noire, pour absorber la chaleur. La fourrure translucide laisse passer la lumière jusqu'à elle."],
["Pourquoi l'ours polaire paraît-il blanc ?",["Il a un pigment blanc","Ses poils creux diffusent la lumière","Il se roule dans la neige","Sa graisse remonte en surface"],1,"Aucun pigment blanc : c'est un effet optique, le même que celui qui rend la neige blanche alors que la glace est transparente."]],
d:["extremes","camouflage"]},

{id:"elephant-afrique",nom:"Éléphant de savane d'Afrique",sci:"Loxodonta africana",emo:"🐘",gr:"Mammifère",ord:"Proboscidea",fam:"Éléphantidés",bio:"savane",
hab:"Savanes, forêts claires",rep:"Afrique subsaharienne",taille:"3 à 4 m au garrot",poidsKg:6000,vit:40,vie:65,
reg:"Herbivore",uicn:"EN",rar:3,
res:"Le plus gros animal terrestre actuel. Sa trompe est l'organe le plus complexe du règne animal après la main humaine.",
f:[["La trompe ne contient aucun os. Elle est faite de dizaines de milliers de faisceaux musculaires qui permettent à la fois de déraciner un arbre et de ramasser une cacahuète.","base"],
["Les éléphants parlent en infrasons, sous 20 Hz — trop grave pour l'oreille humaine. Ces ondes portent à plus de 10 km et voyagent aussi dans le sol : les éléphants les captent par les coussinets de leurs pieds et les os de leurs pattes.","expert"],
["Un troupeau est dirigé par une matriarche, la plus âgée. Sa mémoire des points d'eau lointains peut sauver le groupe pendant une sécheresse. Tuer les vieilles femelles désorganise durablement une population.","pointu"],
["Ils changent de dents six fois dans leur vie. Quand la sixième molaire s'use, l'animal ne peut plus broyer et meurt de faim. C'est la vraie limite de leur longévité.","expert"]],
v:[["Infrason","Son trop grave pour l'oreille humaine (moins de 20 Hz). Il porte beaucoup plus loin que les sons aigus car il traverse la végétation sans être absorbé."]],
q:[["Comment un éléphant capte-t-il les infrasons de ses congénères lointains ?",["Par ses défenses","Par les coussinets de ses pieds","Par sa trompe uniquement","Par ses oreilles seulement"],1,"Les vibrations traversent le sol et remontent par les pieds et les os des pattes jusqu'à l'oreille interne."],
["Qu'est-ce qui limite la durée de vie d'un éléphant ?",["Son cœur","L'usure de sa sixième série de molaires","La taille de ses défenses","Son foie"],1,"Six jeux de molaires, pas un de plus. Quand le dernier est usé, il ne peut plus s'alimenter."]],
d:["sens","records"]},

{id:"girafe",nom:"Girafe",sci:"Giraffa camelopardalis",emo:"🦒",gr:"Mammifère",ord:"Artiodactyla",fam:"Giraffidés",bio:"savane",
hab:"Savanes arborées",rep:"Afrique subsaharienne",taille:"4,5 à 5,5 m",poidsKg:1200,vit:60,vie:25,
reg:"Herbivore",uicn:"VU",rar:2,
res:"Le plus grand animal terrestre. Sa taille l'oblige à des solutions de plomberie que peu d'animaux ont dû inventer.",
f:[["Son cou de deux mètres ne contient que sept vertèbres — le même nombre que le tien. Elles sont juste énormes.","base"],
["Son cœur doit envoyer le sang deux mètres plus haut, ce qui suppose une pression artérielle deux fois supérieure à la nôtre. Quand elle baisse la tête pour boire, un réseau de vaisseaux appelé rete mirabile amortit le flux, et des valves empêchent le sang de refluer vers le crâne. Sans ça, elle s'évanouirait à chaque gorgée.","expert"],
["Les mâles se battent au « necking » : ils balancent leur cou comme un fouet pour frapper l'adversaire avec leurs ossicônes. Un coup peut briser une mâchoire.","pointu"],
["La peau de ses pattes est si serrée qu'elle joue le rôle d'un bas de contention de pilote de chasse. La NASA s'en est inspirée pour ses combinaisons anti-G.","pointu"]],
v:[["Rete mirabile","Littéralement « réseau admirable » : un lacis de petits vaisseaux qui ralentit et régule le flux sanguin. On en trouve aussi chez les thons et les dauphins, pour d'autres usages."]],
q:[["Combien de vertèbres cervicales a une girafe ?",["7","14","24","32"],0,"Sept, comme la souris et l'humain. Chez la girafe, chacune mesure jusqu'à 25 cm."],
["Que se passerait-il si la girafe n'avait pas de rete mirabile ?",["Elle ne pourrait pas courir","Elle s'évanouirait en baissant la tête","Elle ne digérerait pas","Elle ne pourrait pas réguler sa température"],1,"La pression sanguine nécessaire pour irriguer sa tête inonderait son cerveau dès qu'elle se penche."]],
d:["records","convergence"]},

{id:"guepard",nom:"Guépard",sci:"Acinonyx jubatus",emo:"🐆",gr:"Mammifère",ord:"Carnivora",fam:"Félidés",bio:"savane",
hab:"Savanes ouvertes, semi-déserts",rep:"Afrique, poche en Iran",taille:"1,1 à 1,5 m",poidsKg:55,vit:105,vie:12,
reg:"Carnivore",uicn:"VU",rar:3,
res:"L'animal terrestre le plus rapide. Toute son anatomie a été sacrifiée à cette unique fonction — y compris sa capacité à se battre.",
f:[["Il passe de 0 à 100 km/h en trois secondes, mieux qu'une supercar. Mais il ne tient que 20 à 30 secondes avant la surchauffe.","base"],
["Ses griffes sont semi-rétractiles : elles restent sorties comme des crampons de sprinteur. C'est le seul félin dans ce cas.","pointu"],
["Sa colonne vertébrale fonctionne comme un ressort : elle se plie et se détend à chaque foulée, ce qui allonge la course jusqu'à 7 mètres par bond. Pendant plus de la moitié de la course, aucune patte ne touche le sol.","pointu"],
["Des mesures sur guépards sauvages ont montré que le secret n'est pas la vitesse de pointe mais l'accélération et surtout la décélération : il peut perdre 4 m/s en une seule foulée. Il gagne dans les virages, pas en ligne droite.","expert"],
["Tous les guépards actuels descendent d'une poignée de survivants d'un goulot d'étranglement génétique il y a environ 12 000 ans. Ils sont si proches génétiquement qu'une greffe de peau entre deux individus non apparentés n'est pas rejetée.","expert"]],
v:[["Goulot d'étranglement génétique","Effondrement du nombre d'individus qui appauvrit durablement la diversité génétique d'une espèce, même si elle remonte en nombre ensuite."]],
q:[["Quel est le véritable avantage du guépard sur ses proies ?",["Sa vitesse de pointe","Son accélération et sa capacité à freiner en virage","Son endurance","Sa vision nocturne"],1,"Les gazelles virent sec. Le guépard gagne parce qu'il peut virer avec elles à haute vitesse."],
["Qu'est-ce qui rend les guépards génétiquement particuliers ?",["Ils ont deux fois plus de chromosomes","Ils sont presque clones les uns des autres","Ils n'ont pas de chromosome Y","Leur ADN mute très vite"],1,"Un goulot d'étranglement ancien a réduit leur diversité au point que les greffes de peau entre inconnus prennent."]],
d:["records","convergence"]},

{id:"orque",nom:"Orque",sci:"Orcinus orca",emo:"🐋",gr:"Mammifère",ord:"Cetacea",fam:"Delphinidés",bio:"ocean",
hab:"Tous les océans",rep:"Mondiale, des tropiques aux pôles",taille:"6 à 9 m",poidsKg:5500,vit:56,vie:60,
reg:"Carnivore",uicn:"DD",rar:4,
res:"Le plus grand des dauphins et le prédateur au sommet de tous les océans. Une espèce en train, peut-être, de se scinder en plusieurs.",
f:[["C'est un dauphin, pas une baleine. Le plus grand de la famille des delphinidés.","base"],
["Il existe des écotypes qui vivent au même endroit sans jamais se mélanger : les « résidents » mangent du saumon, les « transients » mangent des mammifères marins. Ils ne se reproduisent pas entre eux, n'ont pas les mêmes cris, pas les mêmes techniques de chasse. Génétiquement, ils divergent depuis des centaines de milliers d'années.","expert"],
["Chaque famille a son dialecte, transmis par la mère. Un chercheur peut identifier le clan d'une orque à l'oreille.","pointu"],
["Les femelles connaissent la ménopause et vivent 30 ou 40 ans après. Seules cinq espèces au monde font ça — dont nous. Les grand-mères orques mènent le groupe vers la nourriture les années difficiles.","expert"],
["Certaines créent des vagues avec leur corps pour faire glisser un phoque de sa banquise. La technique s'apprend et se transmet : c'est de la culture animale.","pointu"]],
v:[["Écotype","Population d'une même espèce adaptée à un mode de vie particulier, au point d'en différer par le comportement, le régime et parfois l'anatomie."]],
q:[["Que mangent les orques « transients » du Pacifique nord-est ?",["Du saumon","Des mammifères marins","Du krill","Des raies"],1,"Les résidents mangent du poisson, les transients des phoques et des baleineaux. Les deux s'ignorent superbement."],
["Quelle particularité rare l'orque partage-t-elle avec l'humain ?",["Le pouce opposable","La ménopause","La vision trichromatique","Les empreintes digitales"],1,"Les femelles cessent de se reproduire vers 40 ans et vivent des décennies de plus, au service du groupe."]],
d:["outils","records"]},

{id:"baleine-bleue",nom:"Baleine bleue",sci:"Balaenoptera musculus",emo:"🐳",gr:"Mammifère",ord:"Cetacea",fam:"Balénoptéridés",bio:"ocean",
hab:"Haute mer",rep:"Tous les océans",taille:"24 à 30 m",poidsKg:150000,vit:37,vie:85,
reg:"Planctonophage",uicn:"EN",rar:5,
res:"Le plus gros animal ayant jamais existé sur Terre — plus lourd que n'importe quel dinosaure connu.",
f:[["Son cœur pèse environ 180 kg et bat parfois deux fois par minute en plongée profonde.","base"],
["Sa langue pèse le poids d'un éléphant. Sa bouche peut contenir 90 tonnes d'eau — mais sa gorge ne laisserait pas passer un ballon de football.","base"],
["Elle mange en fonçant bouche ouverte dans un banc de krill à 11 km/h. Chaque gorgée avale un volume d'eau supérieur à son propre corps, puis elle la refoule à travers ses fanons. Une seule bouchée peut rapporter 500 000 calories.","pointu"],
["Ses vocalisations atteignent 188 décibels, plus fort qu'un réacteur d'avion, à des fréquences de 10-20 Hz qui traversent des bassins océaniques entiers.","expert"],
["Les fanons ne sont pas des dents : c'est de la kératine, la même matière que tes ongles et tes cheveux.","base"]],
v:[["Fanon","Lame de kératine suspendue à la mâchoire supérieure qui filtre l'eau et retient le plancton. Les baleines à fanons (mysticètes) s'opposent aux baleines à dents (odontocètes) comme le cachalot."]],
q:[["De quoi sont faits les fanons d'une baleine bleue ?",["D'os","De cartilage","De kératine","D'ivoire"],2,"La même protéine que tes ongles, tes cheveux et les écailles du pangolin."],
["Quelle est la principale nourriture de la baleine bleue ?",["Des poissons","Du krill","Des calmars","Du plancton végétal"],1,"Jusqu'à 4 tonnes de krill par jour en saison d'alimentation."]],
d:["records"]},

{id:"cachalot",nom:"Cachalot",sci:"Physeter macrocephalus",emo:"🐋",gr:"Mammifère",ord:"Cetacea",fam:"Physétéridés",bio:"abysse",
hab:"Océan profond",rep:"Mondiale",taille:"16 à 18 m (mâle)",poidsKg:45000,vit:35,vie:70,
reg:"Carnivore",uicn:"VU",rar:4,
res:"Le plus gros prédateur à dents de la planète, et le détenteur du plus gros cerveau jamais apparu dans le vivant.",
f:[["Son cerveau pèse 7 à 9 kg, cinq à six fois le nôtre.","base"],
["Il plonge à plus de 2 000 m et reste jusqu'à 90 minutes en apnée pour chasser des calmars géants. On retrouve sur sa peau les cicatrices en ventouse de ses adversaires.","base"],
["Ses clics d'écholocation atteignent 230 décibels — les sons les plus puissants produits par un être vivant. À bout portant, un tel clic peut assourdir.","expert"],
["Le tiers avant de son corps est un organe rempli de spermaceti, une cire qui focalise le son comme une lentille acoustique et sert peut-être aussi de régulateur de flottabilité.","expert"],
["Les cachalots dorment à la verticale, immobiles, tête en haut, par groupes de plusieurs individus. On ne l'a découvert qu'en 2008, par hasard.","pointu"]],
v:[["Écholocation","Émettre un son et lire son écho pour cartographier l'environnement. Inventée séparément par les chauves-souris, les cétacés à dents et quelques oiseaux."]],
q:[["Quel animal possède le plus gros cerveau de la planète ?",["La baleine bleue","Le cachalot","L'éléphant","L'humain"],1,"7 à 9 kg — la baleine bleue est bien plus grosse mais son cerveau est plus petit."],
["Pourquoi le cachalot plonge-t-il si profond ?",["Pour dormir","Pour chasser des calmars","Pour fuir les orques","Pour réguler sa température"],1,"Ses proies principales vivent dans la zone crépusculaire et au-delà, entre 500 et 2 000 m."]],
d:["sens","records","abysses"]},

{id:"narval",nom:"Narval",sci:"Monodon monoceros",emo:"🐳",gr:"Mammifère",ord:"Cetacea",fam:"Monodontidés",bio:"polaire",
hab:"Eaux arctiques et banquise",rep:"Arctique atlantique",taille:"4 à 5 m (hors défense)",poidsKg:1600,vit:22,vie:50,
reg:"Carnivore",uicn:"LC",rar:4,
res:"La « licorne des mers ». Sa défense a nourri des siècles de commerce frauduleux avant qu'on comprenne à quoi elle sert.",
f:[["Sa « corne » est en réalité une canine gauche qui pousse en spirale et traverse la lèvre supérieure. Elle peut dépasser 3 mètres.","base"],
["Au Moyen Âge, les défenses de narval étaient vendues aux rois d'Europe comme cornes de licorne, au prix de leur poids en or. Le trône du Danemark en est fait.","pointu"],
["Cette dent contient environ dix millions de terminaisons nerveuses connectées à l'extérieur. C'est un organe sensoriel : le narval y lit sans doute la salinité, la température, la présence de proies.","expert"],
["On les a filmés frappant des cabillauds avec leur défense pour les assommer avant de les avaler.","pointu"]],
v:[["Canine","Dent pointue située entre les incisives et les prémolaires. Chez le narval, une seule des deux pousse, presque toujours la gauche."]],
q:[["Qu'est-ce que la « corne » du narval ?",["Un os du crâne","Une canine gauche","Une corne de kératine","Une nageoire modifiée"],1,"Une dent, qui perce la lèvre et pousse en spirale toute la vie de l'animal."],
["À quoi sert principalement cette défense, selon les recherches récentes ?",["À creuser la glace","C'est un organe sensoriel","À se défendre des ours","À stocker de la graisse"],1,"Dix millions de terminaisons nerveuses ouvertes sur l'eau : le narval « goûte » son environnement avec."]],
d:["sens"]},

{id:"chauve-souris-vampire",nom:"Vampire commun",sci:"Desmodus rotundus",emo:"🦇",gr:"Mammifère",ord:"Chiroptera",fam:"Phyllostomidés",bio:"jungle",
hab:"Grottes, arbres creux",rep:"Amérique centrale et du Sud",taille:"9 cm, 18 cm d'envergure",poidsKg:0.04,vit:30,vie:9,
reg:"Hématophage",uicn:"LC",rar:3,
res:"L'un des trois seuls mammifères au monde à ne se nourrir que de sang. Et l'un des plus généreux.",
f:[["Il ne « suce » pas : il fait une entaille indolore avec ses incisives et lape le sang qui coule.","base"],
["Sa salive contient un anticoagulant baptisé draculine, qui empêche la plaie de se refermer. On l'a étudié pour traiter les AVC.","pointu"],
["Il a des thermorécepteurs sur le nez, capables de repérer à distance les vaisseaux sanguins les plus proches de la peau. Aucun autre mammifère n'a ça.","expert"],
["Un vampire meurt s'il jeûne trois nuits d'affilée. Alors ceux qui ont bien mangé régurgitent du sang pour nourrir les autres — y compris des individus qui ne sont pas de leur famille. Et ils gardent le compte : ceux qui ne rendent jamais la pareille finissent par ne plus être nourris. C'est l'un des cas les plus nets d'altruisme réciproque connus chez un animal.","expert"]],
v:[["Altruisme réciproque","Aider quelqu'un aujourd'hui parce qu'il vous aidera demain. Ça n'est stable que si les individus se reconnaissent et se souviennent — ce que font les vampires."]],
q:[["Que se passe-t-il si un vampire ne mange pas pendant trois nuits ?",["Il hiberne","Il meurt","Il change de régime","Il double son territoire"],1,"D'où le système de partage : sans lui, la mortalité serait énorme."],
["Qu'est-ce que la draculine ?",["Un venin","Un anticoagulant de sa salive","Une hormone du sommeil","Un pigment"],1,"Elle empêche le sang de coaguler pendant que la chauve-souris lape."]],
d:["sens","symbiose"]},

{id:"ornithorynque",nom:"Ornithorynque",sci:"Ornithorhynchus anatinus",emo:"🦫",gr:"Mammifère",ord:"Monotremata",fam:"Ornithorhynchidés",bio:"riviere",
hab:"Rivières et lacs",rep:"Est de l'Australie, Tasmanie",taille:"40 à 50 cm",poidsKg:1.7,vit:null,vie:17,
reg:"Carnivore",uicn:"NT",rar:5,
res:"Un mammifère qui pond des œufs, transpire du lait, détecte l'électricité et porte du venin. Les premiers naturalistes ont cru à un canular.",
f:[["Quand le premier spécimen est arrivé à Londres en 1799, les scientifiques ont cherché les points de couture : ils étaient convaincus qu'on avait cousu un bec de canard sur une taupe.","base"],
["C'est un monotrème : il pond des œufs. Et il n'a pas de mamelons — le lait suinte à travers la peau du ventre et les petits le lapent dans les plis.","pointu"],
["Il chasse les yeux, les oreilles et les narines fermés. Son bec mou est couvert de milliers d'électrorécepteurs qui captent les micro-courants des muscles de ses proies. Il chasse littéralement à l'électricité.","expert"],
["Le mâle porte un éperon venimeux à la patte arrière. Le venin ne tue pas un humain mais provoque une douleur si intense que la morphine n'y fait rien — elle peut durer des semaines.","expert"],
["Sous lumière ultraviolette, sa fourrure devient fluorescente bleu-vert. Découvert en 2020, et on ne sait toujours pas pourquoi.","pointu"]],
v:[["Monotrème","Mammifère qui pond des œufs. Il n'en reste que cinq espèces : l'ornithorynque et quatre échidnés. Une lignée séparée des autres mammifères depuis plus de 160 millions d'années."]],
q:[["Comment l'ornithorynque localise-t-il ses proies sous l'eau ?",["À la vue","Par électroréception","Par écholocation","À l'odorat"],1,"Yeux et oreilles fermés, il lit les champs électriques produits par les muscles des crevettes et larves."],
["Qu'est-ce qu'un monotrème ?",["Un mammifère qui pond des œufs","Un mammifère à poche","Un mammifère venimeux","Un mammifère aquatique"],0,"Cinq espèces au monde : l'ornithorynque et les échidnés."]],
d:["sens","venins","taxo"]},

{id:"echidne",nom:"Échidné à nez court",sci:"Tachyglossus aculeatus",emo:"🦔",gr:"Mammifère",ord:"Monotremata",fam:"Tachyglossidés",bio:"foret",
hab:"Forêts, déserts, montagnes",rep:"Australie, Nouvelle-Guinée",taille:"30 à 45 cm",poidsKg:5,vit:null,vie:16,
reg:"Insectivore",uicn:"LC",rar:4,
res:"L'autre monotrème. Il pond, il allaite, il se hérisse — et son anatomie sexuelle défie l'imagination.",
f:[["Comme l'ornithorynque, il pond un œuf. Il le dépose directement dans une poche ventrale temporaire, où le petit — appelé « puggle » — éclot dix jours plus tard.","base"],
["Le mâle possède un pénis à quatre têtes. Il en utilise deux à la fois, en alternance.","pointu"],
["Pendant la saison de reproduction, jusqu'à dix mâles suivent une femelle à la file indienne pendant des semaines. On appelle ça un « train d'échidnés ».","pointu"],
["Il supporte des températures corporelles qui tueraient la plupart des mammifères et peut entrer en torpeur profonde. Des échidnés ont survécu à des feux de brousse en s'enfouissant et en abaissant leur métabolisme.","expert"]],
v:[["Torpeur","Baisse volontaire et réversible de la température du corps et du métabolisme pour économiser l'énergie. L'hibernation en est une version longue."]],
q:[["Comment naît un jeune échidné ?",["D'un œuf déposé dans une poche","Vivant, comme un marsupial","D'un œuf enterré","Dans un nid collectif"],0,"Un œuf, une poche, et un puggle qui éclot dedans."],
["Comment s'appelle un bébé échidné ?",["Un joey","Un puggle","Un kit","Un nymphe"],1,"Puggle — le mot vaut aussi pour le bébé ornithorynque."]],
d:["taxo","extremes"]},

{id:"paresseux",nom:"Paresseux à gorge brune",sci:"Bradypus variegatus",emo:"🦥",gr:"Mammifère",ord:"Pilosa",fam:"Bradypodidés",bio:"jungle",
hab:"Canopée tropicale",rep:"Amérique centrale et du Sud",taille:"45 à 75 cm",poidsKg:4.5,vit:0.24,vie:30,
reg:"Herbivore",uicn:"LC",rar:2,
res:"Il est lent parce que ses feuilles ne lui donnent presque aucune énergie. Cette lenteur est devenue son camouflage.",
f:[["Une feuille avalée met jusqu'à un mois à être digérée. Son estomac à plusieurs poches peut représenter le tiers de son poids.","base"],
["Il descend au sol pour déféquer environ une fois par semaine — le moment le plus dangereux de sa vie, où se produit une large part de la mortalité par prédation. Pourquoi il ne le fait pas depuis l'arbre reste débattu : la piste la plus sérieuse implique les mites qui vivent dans son pelage.","expert"],
["Sa fourrure abrite des algues vertes qui le camouflent, et tout un écosystème de mites, coléoptères et champignons. Certains de ces champignons produisent des molécules actives contre le paludisme et certains cancers.","expert"],
["Sa lenteur le rend quasi invisible pour la harpie féroce, un aigle qui repère surtout le mouvement.","pointu"],
["Il est trois fois plus fort qu'un humain à poids égal, mais ne peut pas frissonner — ce qui le rend très vulnérable au froid.","pointu"]],
v:[["Canopée","Étage supérieur d'une forêt, formé par la cime des grands arbres. Un habitat à part entière, où vivent des espèces qui ne descendent jamais."]],
q:[["Pourquoi le paresseux est-il si lent ?",["Ses muscles sont atrophiés","Son régime de feuilles lui fournit très peu d'énergie","Il est constamment endormi","Ses articulations sont bloquées"],1,"Les feuilles sont pauvres et longues à digérer. La lenteur est une stratégie d'économie."],
["Quel est le moment le plus dangereux de la vie d'un paresseux ?",["La mise bas","Sa descente hebdomadaire au sol","Le passage d'un arbre à l'autre","La saison des pluies"],1,"Au sol, il est presque sans défense — et c'est là que beaucoup se font tuer."]],
d:["camouflage","symbiose"]},

{id:"tamanoir",nom:"Tamanoir",sci:"Myrmecophaga tridactyla",emo:"🐜",gr:"Mammifère",ord:"Pilosa",fam:"Myrmécophagidés",bio:"savane",
hab:"Savanes et forêts",rep:"Amérique centrale et du Sud",taille:"1,8 à 2,4 m",poidsKg:40,vit:30,vie:16,
reg:"Insectivore",uicn:"VU",rar:3,
res:"Un mammifère sans une seule dent, qui mange 30 000 insectes par jour avec une langue de 60 centimètres.",
f:[["Sa langue mesure jusqu'à 60 cm et sort 150 fois par minute, enduite d'une salive collante.","base"],
["Il n'a aucune dent. Son estomac broie les fourmis avec des muscles puissants et… du sable avalé volontairement.","pointu"],
["Il ne détruit jamais une fourmilière : il y passe une minute environ, prend sa part et s'en va avant que les soldats ne se mobilisent. Il exploite des centaines de nids en rotation, ce qui laisse chaque colonie se reconstituer. C'est une prédation durable.","expert"],
["Sa température corporelle est de 32,7 °C, l'une des plus basses de tous les mammifères — encore une conséquence d'un régime pauvre.","expert"],
["Dressé sur ses pattes arrière, il peut éventrer un jaguar d'un coup de griffe. Des attaques mortelles sur des humains sont documentées.","pointu"]],
v:[["Myrmécophage","Qui mange des fourmis. Le mot vient du grec myrmex, fourmi. On le retrouve dans le nom scientifique de l'espèce."]],
q:[["Pourquoi le tamanoir quitte-t-il une fourmilière au bout d'une minute ?",["Il est vite rassasié","Pour éviter les soldats et laisser la colonie se reconstituer","Les fourmis deviennent toxiques","Il craint les prédateurs"],1,"Une exploitation en rotation qui ne détruit jamais la ressource."],
["Combien de dents possède un tamanoir ?",["Aucune","4","20","32"],0,"Zéro. Son estomac fait le travail, aidé par le sable qu'il avale."]],
d:["records"]},

{id:"pangolin",nom:"Pangolin de Java",sci:"Manis javanica",emo:"🐾",gr:"Mammifère",ord:"Pholidota",fam:"Manidés",bio:"jungle",
hab:"Forêts et plantations",rep:"Asie du Sud-Est",taille:"40 à 65 cm",poidsKg:7,vit:5,vie:20,
reg:"Insectivore",uicn:"CR",rar:5,
res:"Le seul mammifère au monde couvert d'écailles. Et le mammifère sauvage le plus trafiqué de la planète.",
f:[["Ses écailles sont en kératine — la même matière que tes ongles. Elles représentent jusqu'à 20 % de son poids.","base"],
["Menacé, il se roule en boule si serrée qu'un lion ne peut pas l'ouvrir. Le mot « pangolin » vient du malais pengguling, « celui qui s'enroule ».","base"],
["Il n'est pas apparenté aux tatous ni aux fourmiliers malgré la ressemblance : c'est de la convergence évolutive. Ses plus proches cousins sont… les carnivores, chiens et chats compris.","expert"],
["Plus d'un million de pangolins ont été braconnés en dix ans, pour leurs écailles utilisées en médecine traditionnelle — alors qu'elles n'ont aucune propriété médicale, étant chimiquement identiques à un ongle humain.","pointu"]],
v:[["Convergence évolutive","Quand deux espèces sans lien de parenté développent la même solution parce qu'elles affrontent le même problème. Pangolins, tatous et fourmiliers mangent des fourmis, donc se ressemblent — sans être cousins."]],
q:[["De quoi sont faites les écailles du pangolin ?",["D'os","De kératine","D'émail dentaire","De chitine"],1,"De la kératine, comme tes ongles — d'où l'absurdité de leur usage médicinal."],
["Quels sont les plus proches parents du pangolin ?",["Les tatous","Les fourmiliers","Les carnivores (chiens, chats)","Les rongeurs"],2,"La ressemblance avec les tatous est une convergence, pas une parenté."]],
d:["convergence","taxo"]},

{id:"glouton",nom:"Glouton (carcajou)",sci:"Gulo gulo",emo:"🦡",gr:"Mammifère",ord:"Carnivora",fam:"Mustélidés",bio:"foret",
hab:"Taïga et toundra",rep:"Nord de l'Eurasie et Amérique",taille:"65 à 105 cm",poidsKg:15,vit:48,vie:12,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Une grosse belette de 15 kg qui chasse des rennes et vole leur repas aux ours. Le plus mauvais caractère du règne animal.",
f:[["Il appartient à la famille des mustélidés — celle des belettes, blaireaux et loutres. C'est le plus gros représentant terrestre.","base"],
["Sa molaire supérieure arrière est tournée à 90° vers l'intérieur, ce qui lui permet d'arracher de la viande et de broyer des os entièrement gelés. Il mange des carcasses que rien d'autre ne peut entamer.","expert"],
["Il tue régulièrement des proies cinq à dix fois plus lourdes que lui, comme des rennes, en profitant de la neige profonde où ses larges pattes le portent et où l'autre s'enfonce.","pointu"],
["Un mâle peut parcourir 500 km² de territoire et marcher 40 km en une journée.","pointu"]],
v:[["Mustélidés","Famille de carnivores allongés et souples : belettes, hermines, martres, blaireaux, loutres, gloutons. Presque tous ont des glandes anales très odorantes."]],
q:[["À quelle famille appartient le glouton ?",["Les ursidés (ours)","Les mustélidés (belettes)","Les canidés","Les viverridés"],1,"C'est une belette de 15 kg — d'où le tempérament."],
["Quelle particularité anatomique lui permet de manger de la viande gelée ?",["Des incisives en scie","Une molaire tournée à 90°","Une mâchoire déboîtable","Des dents à croissance continue"],1,"Cette molaire retournée fonctionne comme une cisaille à os congelés."]],
d:["extremes"]},

{id:"loutre-de-mer",nom:"Loutre de mer",sci:"Enhydra lutris",emo:"🦦",gr:"Mammifère",ord:"Carnivora",fam:"Mustélidés",bio:"ocean",
hab:"Forêts de kelp côtières",rep:"Pacifique nord",taille:"1 à 1,5 m",poidsKg:30,vit:9,vie:20,
reg:"Carnivore",uicn:"EN",rar:4,
res:"Le mammifère marin sans graisse isolante. Elle compense par la fourrure la plus dense du monde animal — ce qui a failli lui coûter l'existence.",
f:[["Elle n'a pas de couche de graisse. Sa fourrure compte jusqu'à 150 000 poils par centimètre carré : plus de poils sur une main que sur toute ta tête.","base"],
["Elle utilise une pierre pour ouvrir oursins et coquillages, et la range dans une poche de peau sous l'aisselle. Certaines gardent la même pierre des années. C'est un des rares mammifères non-primates à utiliser des outils.","pointu"],
["Elle mange jusqu'à 25 % de son poids par jour pour tenir la température.","base"],
["C'est une espèce clé de voûte : elle mange les oursins, les oursins mangent le kelp. Là où les loutres ont disparu, les oursins ont rasé les forêts sous-marines et laissé des déserts. Leur retour a fait repousser le kelp — donc les poissons, donc les oiseaux.","expert"],
["Elles se tiennent la patte en dormant pour ne pas dériver, ou s'enroulent dans une lanière de kelp.","base"]],
v:[["Espèce clé de voûte","Espèce dont l'impact sur son écosystème est disproportionné par rapport à son abondance. La retirer fait s'effondrer tout l'édifice."]],
q:[["Pourquoi la loutre de mer mange-t-elle un quart de son poids par jour ?",["Elle a un très gros estomac","Elle n'a pas de graisse isolante et doit brûler pour se chauffer","Elle nourrit ses petits","Elle stocke pour l'hiver"],1,"Sans graisse, la seule solution est de produire de la chaleur en permanence."],
["Qu'arrive-t-il à une forêt de kelp quand les loutres disparaissent ?",["Elle prolifère","Les oursins la rasent","Elle devient toxique","Rien de particulier"],1,"Un cas d'école de cascade trophique : loutres → oursins → kelp."]],
d:["outils","symbiose"]},

{id:"rat-taupe-nu",nom:"Rat-taupe nu",sci:"Heterocephalus glaber",emo:"🐀",gr:"Mammifère",ord:"Rodentia",fam:"Hétérocéphalidés",bio:"souterrain",
hab:"Galeries souterraines",rep:"Corne de l'Afrique",taille:"8 à 10 cm",poidsKg:0.035,vit:null,vie:32,
reg:"Herbivore",uicn:"LC",rar:5,
res:"Un rongeur nu, aveugle, à sang quasi froid, qui vit comme une fourmi, ignore la douleur acide et ne vieillit presque pas. Chaque ligne de sa biologie est une exception.",
f:[["Il est eusocial, comme les fourmis : une seule femelle, la reine, se reproduit. Les autres creusent, nourrissent ou défendent. C'est l'un des deux seuls mammifères connus dans ce cas.","pointu"],
["Il est insensible à la douleur causée par l'acide et la capsaïcine (le piment) : une adaptation à l'air très chargé en CO₂ de ses galeries, qui acidifie les tissus.","expert"],
["Il survit 18 minutes sans oxygène. Quand l'air manque, son métabolisme bascule sur le fructose — un mode de secours qu'on ne connaissait que chez les plantes.","expert"],
["Il vit plus de 30 ans, dix fois plus qu'une souris de taille comparable, et son risque de mourir n'augmente pas avec l'âge. Il échappe donc à la loi de Gompertz, qui décrit le vieillissement de presque tous les animaux.","expert"],
["Les cancers y sont extrêmement rares. On soupçonne un acide hyaluronique de très haut poids moléculaire qui empêche les cellules de s'entasser.","pointu"]],
v:[["Eusocialité","Organisation sociale avec division du travail reproducteur : une caste se reproduit, les autres travaillent. Presque toujours chez les insectes — et chez deux rongeurs africains."]],
q:[["Qu'est-ce qui rend le rat-taupe nu unique parmi les mammifères ?",["Il est eusocial comme les fourmis","Il pond des œufs","Il change de sexe","Il photosynthétise"],0,"Une reine, des ouvriers, des soldats. Chez un mammifère."],
["Que fait son métabolisme quand l'oxygène manque ?",["Il s'arrête","Il bascule sur le fructose","Il utilise l'azote","Il ralentit le cœur à zéro"],1,"Un mode de secours anaérobie qu'on ne connaissait que chez les végétaux."]],
d:["eusocial","extremes","records"]},

{id:"tarsier",nom:"Tarsier des Philippines",sci:"Carlito syrichta",emo:"👀",gr:"Mammifère",ord:"Primates",fam:"Tarsiidés",bio:"jungle",
hab:"Forêts secondaires",rep:"Philippines",taille:"9 à 16 cm",poidsKg:0.13,vit:null,vie:16,
reg:"Carnivore",uicn:"NT",rar:4,
res:"Un primate de la taille d'un poing dont chaque œil pèse autant que son cerveau. Le seul primate strictement carnivore.",
f:[["Chacun de ses yeux a le volume de son cerveau. Rapporté à la taille, ce sont les plus gros yeux de tous les mammifères.","base"],
["Ces yeux sont si gros qu'ils ne peuvent pas bouger dans leurs orbites. Compensation : il tourne la tête à 180° de chaque côté, comme une chouette.","pointu"],
["Contrairement à tous les autres primates, il ne mange aucun végétal : insectes, lézards, oiseaux, parfois serpents venimeux.","pointu"],
["Il communique en ultrasons, jusqu'à 70 kHz — inaudible pour nous et pour ses prédateurs. On ne l'a découvert qu'en 2012 : jusque-là on croyait ces tarsiers silencieux, alors qu'ils criaient.","expert"],
["Il saute jusqu'à 40 fois la longueur de son corps grâce à un os du tarse allongé — d'où son nom.","base"]],
v:[["Ultrason","Son trop aigu pour l'oreille humaine (au-dessus de 20 kHz). Utilisé par les chauves-souris, certains rongeurs, et le tarsier — souvent pour communiquer sans être entendu."]],
q:[["Pourquoi le tarsier tourne-t-il la tête à 180° ?",["Pour intimider","Ses yeux ne peuvent pas bouger dans leurs orbites","Pour écholocaliser","Pour dormir"],1,"Des yeux trop gros pour rouler : il faut bouger toute la tête."],
["Qu'est-ce qui distingue le tarsier de tous les autres primates ?",["Il est nocturne","Il est strictement carnivore","Il vit seul","Il n'a pas de queue"],1,"Aucun fruit, aucune feuille : uniquement des proies vivantes."]],
d:["sens","records"]},

{id:"aye-aye",nom:"Aye-aye",sci:"Daubentonia madagascariensis",emo:"🖐️",gr:"Mammifère",ord:"Primates",fam:"Daubentoniidés",bio:"jungle",
hab:"Forêts de Madagascar",rep:"Madagascar",taille:"30 à 40 cm",poidsKg:2.5,vit:null,vie:23,
reg:"Omnivore",uicn:"EN",rar:5,
res:"Un lémurien nocturne qui a réinventé le pic-vert avec un doigt. Considéré comme un présage de mort à Madagascar, il est tué à vue.",
f:[["Son majeur est deux fois plus fin que les autres doigts et monté sur une rotule : il pivote librement dans tous les sens.","base"],
["Il tapote l'écorce avec ce doigt, écoute l'écho avec ses oreilles mobiles pour repérer une galerie creuse, ronge le bois avec ses incisives, puis va harponner la larve. On appelle ça la percussive foraging — le seul primate à faire ça.","expert"],
["Ses incisives poussent en continu, comme celles d'un rongeur. Longtemps, on l'a d'ailleurs classé chez les rongeurs avant de comprendre que c'était un primate.","pointu"],
["Il occupe la niche écologique du pic-vert, absent de Madagascar : même métier, outil différent. Manuel plutôt qu'à bec.","expert"],
["Dans plusieurs régions malgaches, le voir annonce une mort. Beaucoup sont tués pour cette raison — première cause de leur déclin avec la déforestation.","base"]],
v:[["Niche écologique","Le « métier » d'une espèce dans son écosystème : ce qu'elle mange, où, quand, comment. Deux espèces différentes peuvent occuper la même niche sur deux continents."]],
q:[["Comment l'aye-aye trouve-t-il les larves dans le bois ?",["À l'odorat","En tapotant l'écorce et en écoutant l'écho","En creusant au hasard","En suivant les fourmis"],1,"Un sonar manuel : il frappe, il écoute, il perce."],
["Quelle niche écologique l'aye-aye occupe-t-il à Madagascar ?",["Celle du pic-vert","Celle du hibou","Celle de l'écureuil","Celle de la chauve-souris"],0,"Pas de pics à Madagascar : un primate a pris le poste."]],
d:["convergence","sens","outils"]},

{id:"hyene-tachetee",nom:"Hyène tachetée",sci:"Crocuta crocuta",emo:"🦴",gr:"Mammifère",ord:"Carnivora",fam:"Hyénidés",bio:"savane",
hab:"Savanes et brousse",rep:"Afrique subsaharienne",taille:"1,2 à 1,8 m",poidsKg:60,vit:60,vie:20,
reg:"Carnivore",uicn:"LC",rar:3,
res:"Ni chien, ni charognard paresseux : une chasseuse redoutable, organisée en société matriarcale, avec l'une des mâchoires les plus puissantes du continent.",
f:[["Elle n'est pas apparentée aux chiens. Les hyénidés appartiennent aux féliformes : leurs plus proches parents sont les mangoustes et les civettes, donc côté chat.","pointu"],
["Contrairement à sa réputation, elle tue elle-même la majorité de ce qu'elle mange. C'est souvent le lion qui lui vole ses proies, pas l'inverse.","base"],
["Sa mâchoire broie le fémur d'un buffle. Son système digestif dissout os, cornes et dents ; ses excréments sont blancs à force de calcium.","pointu"],
["Le clan est matriarcal : toutes les femelles dominent tous les mâles, et la fille de la matriarche hérite de son rang.","pointu"],
["Les femelles urinent, s'accouplent et mettent bas par un clitoris allongé qui ressemble à un pénis. Le premier accouchement est si difficile qu'une grande part des femelles perdent leur premier petit. Aucune explication évolutive ne fait consensus.","expert"]],
v:[["Féliformes","Grand groupe de carnivores « côté chat » : félins, hyènes, mangoustes, civettes. Face à eux, les caniformes : chiens, ours, mustélidés, phoques."]],
q:[["Quels sont les plus proches parents de la hyène ?",["Les chiens","Les mangoustes et civettes","Les ours","Les loutres"],1,"Elle est féliforme : plus proche du chat que du chien."],
["Comment est organisé un clan de hyènes tachetées ?",["Un mâle dominant","Matriarcal : toutes les femelles dominent les mâles","Sans hiérarchie","Par couples"],1,"Le rang s'hérite de la mère, comme un titre."]],
d:["taxo","records"]},

{id:"fennec",nom:"Fennec",sci:"Vulpes zerda",emo:"🦊",gr:"Mammifère",ord:"Carnivora",fam:"Canidés",bio:"desert",
hab:"Déserts de sable",rep:"Sahara, Sinaï, Arabie",taille:"35 à 40 cm",poidsKg:1.5,vit:32,vie:12,
reg:"Omnivore",uicn:"LC",rar:2,
res:"Le plus petit canidé du monde, et un manuel de survie en milieu aride à lui seul.",
f:[["Ses oreilles font jusqu'à 15 cm pour un corps de 35 cm. Elles sont irriguées de vaisseaux qui évacuent la chaleur : un radiateur.","base"],
["Il peut vivre sans jamais boire : toute son eau vient de ses proies et de ses rares végétaux. Ses reins concentrent l'urine à l'extrême.","pointu"],
["Ses pattes sont couvertes de poils jusque sous les coussinets — des semelles anti-brûlure qui font aussi office de raquettes dans le sable mou.","pointu"],
["La règle d'Allen prédit exactement ça : dans les climats chauds, les appendices s'allongent pour dissiper la chaleur ; dans le froid, ils raccourcissent. Compare le fennec au renard polaire, aux oreilles minuscules : même genre, deux extrêmes.","expert"]],
v:[["Règle d'Allen","Chez des espèces proches, les animaux des climats chauds ont des appendices (oreilles, pattes, queue) plus longs que ceux des climats froids, pour évacuer la chaleur."]],
q:[["À quoi servent d'abord les grandes oreilles du fennec ?",["À entendre les proies uniquement","À évacuer la chaleur","À intimider","À creuser"],1,"Elles servent aussi à écouter sous le sable, mais leur taille s'explique surtout par la thermorégulation."],
["Qu'énonce la règle d'Allen ?",["Les animaux chauds sont plus gros","Les appendices s'allongent en climat chaud","Les prédateurs sont plus rares au pôle","Les espèces insulaires rapetissent"],1,"Compare fennec et renard polaire : même genre Vulpes, oreilles opposées."]],
d:["extremes","convergence"]},

{id:"saiga",nom:"Saïga",sci:"Saiga tatarica",emo:"👃",gr:"Mammifère",ord:"Artiodactyla",fam:"Bovidés",bio:"montagne",
hab:"Steppes arides",rep:"Kazakhstan, Mongolie, Russie",taille:"1,1 à 1,5 m",poidsKg:40,vit:80,vie:10,
reg:"Herbivore",uicn:"NT",rar:4,
res:"Une antilope au nez d'extraterrestre, contemporaine du mammouth, qui a frôlé l'extinction deux fois en vingt ans — et vient de revenir spectaculairement.",
f:[["Son nez énorme et mobile filtre la poussière des steppes en été, et réchauffe l'air glacé avant qu'il n'atteigne les poumons en hiver, à −40 °C.","base"],
["Elle vivait aux côtés des mammouths laineux et des lions des cavernes. C'est un survivant de la mégafaune glaciaire.","pointu"],
["En mai 2015, plus de 200 000 saïgas — les deux tiers de l'espèce mondiale — sont mortes en trois semaines. La cause : une bactérie normalement inoffensive, Pasteurella multocida, devenue mortelle à la faveur d'une chaleur et d'une humidité inhabituelles.","expert"],
["Après cet effondrement, une protection stricte a fait remonter la population de 50 000 à plus de 2 millions d'individus. En 2023, l'UICN l'a fait passer de « en danger critique » à « quasi menacée » : l'un des plus rapides redressements jamais enregistrés.","expert"]],
v:[["Mégafaune","Ensemble des grands animaux (souvent plus de 45 kg). Celle du Pléistocène — mammouths, rhinocéros laineux, saïgas — a presque entièrement disparu il y a 10 000 ans."]],
q:[["À quoi sert le nez de la saïga en hiver ?",["À flairer les prédateurs","À réchauffer l'air avant les poumons","À stocker de l'eau","À produire des sons graves"],1,"Filtre à poussière l'été, radiateur l'hiver."],
["Qu'est-il arrivé aux saïgas en mai 2015 ?",["Une sécheresse","Une bactérie a tué les deux tiers de l'espèce","Un braconnage massif","Une inondation"],1,"200 000 morts en trois semaines à cause d'une bactérie ordinaire devenue létale."]],
d:["retour","extremes"]},

{id:"chameau-bactriane",nom:"Chameau de Bactriane sauvage",sci:"Camelus ferus",emo:"🐫",gr:"Mammifère",ord:"Artiodactyla",fam:"Camélidés",bio:"desert",
hab:"Déserts froids",rep:"Mongolie, Chine (Gobi)",taille:"1,8 à 2,3 m au garrot",poidsKg:600,vit:65,vie:40,
reg:"Herbivore",uicn:"CR",rar:5,
res:"Espèce sauvage distincte du chameau domestique, réduite à moins de mille individus dans le désert de Gobi.",
f:[["Les bosses ne contiennent pas d'eau mais de la graisse — une réserve d'énergie stockée hors du corps pour ne pas gêner la dissipation de chaleur.","base"],
["Il peut boire 100 litres en dix minutes sans que ses cellules éclatent, parce que ses globules rouges sont ovales et élastiques, au lieu d'être ronds comme chez tous les autres mammifères.","expert"],
["Il tolère une variation de sa température corporelle de 34 à 41 °C sur une journée. Ne pas transpirer tant qu'on n'a pas atteint 41 °C, c'est économiser des litres d'eau.","expert"],
["Les populations sauvages du Gobi boivent une eau salée qu'aucun autre mammifère ne supporte — y compris le chameau domestique.","pointu"]],
v:[["Homéothermie","Maintien d'une température corporelle stable. Le chameau la relâche volontairement : on parle d'hétérothermie adaptative, une entorse rentable à la règle."]],
q:[["Que contiennent les bosses d'un chameau ?",["De l'eau","De la graisse","Du sang","De l'air"],1,"De la graisse. Concentrer les réserves ailleurs que sous la peau facilite le refroidissement."],
["Pourquoi le chameau peut-il boire 100 L d'un coup ?",["Son estomac est immense","Ses globules rouges ovales résistent à l'afflux d'eau","Il stocke l'eau dans ses bosses","Il ne l'absorbe pas vraiment"],1,"Des globules ronds éclateraient sous l'arrivée massive d'eau."]],
d:["extremes"]},

{id:"okapi",nom:"Okapi",sci:"Okapia johnstoni",emo:"🦓",gr:"Mammifère",ord:"Artiodactyla",fam:"Giraffidés",bio:"jungle",
hab:"Forêt dense de l'Ituri",rep:"Nord-est de la RD Congo",taille:"1,5 m au garrot",poidsKg:250,vit:60,vie:30,
reg:"Herbivore",uicn:"EN",rar:5,
res:"Le seul parent vivant de la girafe. Resté inconnu de la science jusqu'en 1901, ce qui en fait l'un des derniers grands mammifères découverts.",
f:[["Malgré ses rayures, il n'a rien d'un zèbre : c'est un giraffidé, seul cousin vivant de la girafe.","base"],
["Sa langue préhensile bleu-noir mesure 30 cm : assez pour attraper les feuilles et se nettoyer les yeux et l'intérieur des oreilles.","base"],
["Les rayures des pattes arrière brisent la silhouette dans les jeux d'ombre et de lumière du sous-bois, et servent de repère visuel au petit qui suit sa mère.","pointu"],
["Il communique avec son petit en infrasons, sous le seuil de l'ouïe du léopard, son principal prédateur.","expert"],
["Les Européens l'ont longtemps cru légendaire : les explorateurs parlaient d'une « licorne africaine ». Il n'a été décrit qu'en 1901, alors que les Mbuti le chassaient depuis toujours.","pointu"]],
v:[["Espèce cryptique","Espèce discrète, difficile à observer, parfois restée inconnue de la science longtemps après avoir été bien connue des populations locales."]],
q:[["De quel animal l'okapi est-il le plus proche parent ?",["Le zèbre","La girafe","L'antilope","Le cerf"],1,"Seul autre giraffidé vivant. Ses ossicônes le trahissent."],
["En quelle année l'okapi a-t-il été décrit par la science occidentale ?",["1801","1901","1951","1975"],1,"1901 — l'un des derniers grands mammifères « découverts », alors que les Mbuti le connaissaient depuis toujours."]],
d:["camouflage","sens"]},

{id:"tigre",nom:"Tigre du Bengale",sci:"Panthera tigris tigris",emo:"🐅",gr:"Mammifère",ord:"Carnivora",fam:"Félidés",bio:"jungle",
hab:"Forêts, mangroves, prairies",rep:"Inde, Népal, Bangladesh, Bhoutan",taille:"2,7 à 3,1 m",poidsKg:220,vit:65,vie:15,
reg:"Carnivore",uicn:"EN",rar:4,
res:"Le plus grand félin du monde. Un chasseur solitaire à l'affût, dont il reste moins d'individus sauvages que d'habitants dans un village.",
f:[["Ses rayures sont aussi sur sa peau, pas seulement sur ses poils. Rasé, il resterait rayé. Et le motif est unique à chaque individu, comme une empreinte digitale.","base"],
["Il rugit en produisant des infrasons sous 20 Hz, qui traversent la végétation dense et provoquent une réaction de sidération chez ses proies.","pointu"],
["Il ne réussit qu'une chasse sur dix à vingt. Un tigre passe l'essentiel de son temps à échouer.","pointu"],
["Dans les mangroves des Sundarbans, les tigres nagent d'île en île et boivent une eau saumâtre. Certains ont pris l'habitude d'attaquer des humains — des villageois y portent un masque à l'arrière de la tête, car le tigre attaque presque toujours par-derrière.","expert"],
["Il reste environ 5 500 tigres sauvages contre 100 000 il y a un siècle. Mais la population remonte depuis 2010 : c'est l'une des grandes réussites de la conservation.","base"]],
v:[["Sous-espèce","Population d'une même espèce, isolée géographiquement, aux caractères propres, mais toujours capable de se reproduire avec les autres. Le tigre en compte six vivantes."]],
q:[["Les rayures du tigre sont-elles seulement sur ses poils ?",["Oui","Non, la peau est aussi rayée","Seulement chez les jeunes","Seulement chez les mâles"],1,"Le motif est dans la peau, et il est unique à chaque tigre."],
["Quel est approximativement le taux de réussite d'une chasse de tigre ?",["9 sur 10","1 sur 2","1 sur 10","Toujours réussie"],2,"Le grand prédateur passe surtout son temps à rater."]],
d:["camouflage","sens"]},

{id:"hippopotame",nom:"Hippopotame",sci:"Hippopotamus amphibius",emo:"🦛",gr:"Mammifère",ord:"Artiodactyla",fam:"Hippopotamidés",bio:"riviere",
hab:"Fleuves et lacs",rep:"Afrique subsaharienne",taille:"3,3 à 5 m",poidsKg:1800,vit:30,vie:45,
reg:"Herbivore",uicn:"VU",rar:3,
res:"Le mammifère qui tue le plus d'humains en Afrique. Et, contre toute apparence, le plus proche parent terrestre des baleines.",
f:[["Il ne nage pas vraiment : trop dense pour flotter, il marche et bondit au fond de l'eau en apesanteur relative.","base"],
["Sa « sueur de sang » est un liquide rouge-orangé, l'acide hipposudorique, qui est à la fois un écran solaire et un antiseptique. C'est ce qui empêche ses plaies de s'infecter dans une eau chargée de matière fécale.","expert"],
["Ses plus proches parents vivants sont les cétacés — baleines et dauphins. Leur ancêtre commun vivait il y a environ 55 millions d'années.","pointu"],
["Il sort brouter la nuit et peut parcourir 10 km, avalant 40 kg d'herbe. Il ne mange presque rien dans l'eau.","base"],
["Il « chante » sous l'eau : ses vocalisations se propagent simultanément dans l'air et dans l'eau, et les autres hippopotames répondent aux voix qu'ils reconnaissent.","pointu"]],
v:[["Cétartiodactyles","Groupe qui réunit les artiodactyles (ongulés à doigts pairs : vaches, cochons, hippopotames) et les cétacés. La génétique a montré que les baleines sont des ongulés retournés à l'eau."]],
q:[["Quels sont les plus proches parents vivants de l'hippopotame ?",["Les rhinocéros","Les cochons","Les cétacés","Les éléphants"],2,"Baleines et dauphins. Le rapprochement, longtemps contesté, a été confirmé par la génétique."],
["À quoi sert la « sueur de sang » de l'hippopotame ?",["À attirer des partenaires","Écran solaire et antiseptique","À repousser les crocodiles","À réguler le sel"],1,"Sans elle, ses blessures s'infecteraient dans une eau très sale."]],
d:["taxo","convergence"]},

{id:"koala",nom:"Koala",sci:"Phascolarctos cinereus",emo:"🐨",gr:"Mammifère",ord:"Diprotodontia",fam:"Phascolarctidés",bio:"foret",
hab:"Forêts d'eucalyptus",rep:"Est de l'Australie",taille:"60 à 85 cm",poidsKg:12,vit:10,vie:15,
reg:"Herbivore",uicn:"VU",rar:3,
res:"Un marsupial qui a fait le pari de manger une plante toxique que personne ne veut — et qui paie ce choix par 20 heures de sommeil.",
f:[["Ses empreintes digitales sont si proches des nôtres qu'elles peuvent être confondues sur une scène de crime, au microscope. Une convergence évolutive parfaitement inutile et spectaculaire.","expert"],
["L'eucalyptus est toxique, fibreux et pauvre en calories. Le koala le neutralise dans un cæcum de 2 mètres — le plus long, proportionnellement, de tous les mammifères — et dort 20 heures par jour pour économiser.","pointu"],
["Le jeune ne naît pas avec les bactéries capables de digérer l'eucalyptus. Sa mère produit une bouillie spéciale, le « pap », une forme de fèces molles qu'il mange pour ensemencer ses intestins.","pointu"],
["Il boit très rarement : « koala » viendrait d'un mot dharug signifiant « qui ne boit pas ». Depuis les grands feux, on les observe pourtant boire de plus en plus.","base"],
["Il a l'un des plus petits cerveaux relatifs des mammifères, et lisse plutôt que plissé — encore une économie d'énergie.","expert"]],
v:[["Cæcum","Poche située au début du gros intestin, où fermentent les végétaux difficiles. Chez l'humain, il ne reste que l'appendice ; chez le koala, il fait deux mètres."]],
q:[["Comment un jeune koala acquiert-il les bactéries pour digérer l'eucalyptus ?",["Il naît avec","Il mange le « pap » de sa mère","Par le lait uniquement","Il lèche l'écorce"],1,"Une bouillie fécale maternelle qui ensemence son microbiote."],
["Quelle particularité étonnante partage le koala avec l'humain ?",["Les groupes sanguins","Des empreintes digitales quasi identiques","La vision trichromatique","Le rire"],1,"Une convergence évolutive, sans aucun lien de parenté proche."]],
d:["convergence","symbiose"]},

{id:"kangourou-roux",nom:"Kangourou roux",sci:"Osphranter rufus",emo:"🦘",gr:"Mammifère",ord:"Diprotodontia",fam:"Macropodidés",bio:"desert",
hab:"Plaines arides et semi-arides",rep:"Intérieur de l'Australie",taille:"1,3 à 1,6 m",poidsKg:85,vit:70,vie:22,
reg:"Herbivore",uicn:"LC",rar:2,
res:"Le plus grand marsupial vivant, et l'animal terrestre au mode de déplacement le plus économe qui soit.",
f:[["Plus il va vite, moins il dépense d'énergie par mètre — jusqu'à un certain point. Ses tendons d'Achille fonctionnent comme des ressorts qui restituent l'énergie du bond précédent. Il rebondit presque gratuitement.","expert"],
["Une femelle peut porter trois petits à trois stades différents en même temps : un embryon en pause, un nouveau-né accroché à une tétine, un jeune qui rentre et sort de la poche.","pointu"],
["Elle produit alors deux laits de composition différente dans deux tétines voisines, adaptés à chaque âge.","expert"],
["La diapause embryonnaire lui permet de mettre un embryon en attente jusqu'à ce que les conditions redeviennent favorables — un atout majeur dans un désert où la pluie est imprévisible.","pointu"],
["Il ne peut pas reculer : la forme de ses pattes et sa queue l'en empêchent. Avec l'émeu, également incapable de marche arrière, il figure sur les armoiries australiennes — un pays qui n'avance que.","base"]],
v:[["Diapause embryonnaire","Mise en pause du développement d'un embryon déjà fécondé, en attente de meilleures conditions. On la trouve aussi chez certains ours, mustélidés et chevreuils."]],
q:[["Pourquoi le bond du kangourou est-il si économe ?",["Il est très léger","Ses tendons restituent l'énergie comme des ressorts","Il plane","Ses os sont creux"],1,"Le coût énergétique baisse quand la vitesse augmente — un cas unique."],
["Qu'est-ce que la diapause embryonnaire ?",["Une gestation très longue","La mise en pause d'un embryon fécondé","Une naissance prématurée","Un avortement spontané"],1,"L'embryon attend la pluie pour reprendre son développement."]],
d:["records","extremes"]},

{id:"diable-tasmanie",nom:"Diable de Tasmanie",sci:"Sarcophilus harrisii",emo:"😈",gr:"Mammifère",ord:"Dasyuromorphia",fam:"Dasyuridés",bio:"foret",
hab:"Forêts et bush",rep:"Tasmanie",taille:"55 à 65 cm",poidsKg:8,vit:25,vie:6,
reg:"Carnivore",uicn:"EN",rar:4,
res:"Le plus grand marsupial carnivore vivant, victime d'un cancer contagieux — l'un des trois seuls connus dans tout le règne animal.",
f:[["Rapportée à sa masse, sa morsure est la plus puissante de tous les mammifères vivants. Il broie os, fourrure et crâne : il ne laisse rien.","pointu"],
["La DFTD, tumeur faciale transmissible, se transmet par morsure lors des combats : les cellules cancéreuses passent d'un individu à l'autre comme un parasite. Elle a tué jusqu'à 80 % de la population depuis 1996.","expert"],
["On observe depuis peu une évolution accélérée : certaines populations développent une résistance en quelques générations, et les diables se reproduisent désormais plus jeunes. L'évolution en direct, sous nos yeux.","expert"],
["Ses cris nocturnes — grognements, hurlements, toux — ont terrifié les premiers colons européens, d'où son nom.","base"]],
v:[["Cancer transmissible","Cancer dont les cellules passent physiquement d'un individu à l'autre et continuent d'y proliférer. On n'en connaît que trois : chez le diable de Tasmanie, le chien, et certains bivalves."]],
q:[["Qu'est-ce que la DFTD ?",["Un virus","Un cancer transmissible par morsure","Une bactérie","Un parasite intestinal"],1,"Les cellules tumorales se transmettent physiquement entre individus."],
["Qu'a-t-on observé récemment chez les populations survivantes ?",["Une migration","Une résistance qui évolue en quelques générations","Une hibernation","Un changement de régime"],1,"L'évolution mesurable à l'échelle d'une vie humaine."]],
d:["retour","records"]},

{id:"musaraigne-etrusque",nom:"Musaraigne étrusque",sci:"Suncus etruscus",emo:"🐭",gr:"Mammifère",ord:"Eulipotyphla",fam:"Soricidés",bio:"foret",
hab:"Broussailles, murets, jardins",rep:"Sud de l'Europe à l'Asie du Sud-Est",taille:"3,5 à 5 cm",poidsKg:0.0018,vit:null,vie:2,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Le plus petit mammifère du monde par la masse. Un animal si petit qu'il vit au bord du gouffre métabolique en permanence.",
f:[["Elle pèse moins de 2 grammes — le poids d'une pièce de 1 centime.","base"],
["Son cœur bat jusqu'à 1 500 fois par minute, environ 25 battements par seconde. Elle respire 800 fois par minute.","pointu"],
["Elle doit manger 1,5 à 2 fois son poids chaque jour. Six heures sans nourriture, et elle meurt.","pointu"],
["Elle définit une limite physique : en dessous de cette taille, un mammifère à sang chaud perdrait sa chaleur plus vite qu'il ne peut en produire, parce que la surface augmente moins vite que le volume. Aucune évolution ne peut faire plus petit.","expert"]],
v:[["Rapport surface/volume","Plus un corps est petit, plus sa surface est grande par rapport à son volume — donc plus il perd sa chaleur vite. C'est la contrainte qui fixe la taille minimale d'un animal à sang chaud."]],
q:[["Combien de temps une musaraigne étrusque peut-elle jeûner ?",["3 jours","24 heures","Environ 6 heures","2 semaines"],2,"Son métabolisme est si rapide qu'elle meurt de faim en une demi-journée."],
["Pourquoi aucun mammifère ne peut être plus petit qu'elle ?",["Le cerveau serait trop petit","La perte de chaleur dépasserait la production","Les os seraient trop fragiles","Il ne pourrait pas se reproduire"],1,"Une limite imposée par le rapport surface/volume, pas par le hasard."]],
d:["records","extremes"]},

{id:"bouquetin-alpes",nom:"Bouquetin des Alpes",sci:"Capra ibex",emo:"🐐",gr:"Mammifère",ord:"Artiodactyla",fam:"Bovidés",bio:"montagne",
hab:"Rochers et alpages d'altitude",rep:"Alpes",taille:"1,3 à 1,5 m",poidsKg:90,vit:null,vie:19,
reg:"Herbivore",uicn:"LC",rar:3,
res:"Un grimpeur capable d'escalader un barrage vertical. Et un cas d'école : l'espèce est passée sous les 100 individus avant d'être sauvée.",
f:[["Ses sabots ont un bord dur et un coussinet central mou : une pince et une gomme, comme un chausson d'escalade.","base"],
["Au barrage du Cingino en Italie, des bouquetins escaladent un mur de béton quasi vertical pour lécher le sel des pierres. Les photos sont si improbables qu'on les a longtemps crues truquées.","pointu"],
["Vers 1820, il n'en restait qu'une centaine d'individus, tous dans le massif du Grand-Paradis, sauvés par une réserve royale de chasse. Tous les bouquetins des Alpes actuels — environ 55 000 — descendent de ce noyau.","expert"],
["Conséquence : leur diversité génétique est très faible, ce qui les rend vulnérables aux maladies. Un sauvetage réussi laisse toujours une cicatrice génétique.","expert"]],
v:[["Effet fondateur","Appauvrissement génétique d'une population issue d'un très petit nombre d'ancêtres. Toutes les générations suivantes héritent de cette diversité réduite."]],
q:[["Pourquoi les bouquetins escaladent-ils les barrages ?",["Pour fuir les prédateurs","Pour lécher le sel","Pour rejoindre les femelles","Pour trouver de l'eau"],1,"Le sel des pierres compense les carences minérales de leur régime."],
["De combien d'individus descendent tous les bouquetins des Alpes ?",["Environ 100","Environ 5 000","Environ 50 000","On l'ignore"],0,"Une centaine, dans le Grand-Paradis, vers 1820."]],
d:["retour","extremes"]},

{id:"orang-outan",nom:"Orang-outan de Sumatra",sci:"Pongo abelii",emo:"🦧",gr:"Mammifère",ord:"Primates",fam:"Hominidés",bio:"jungle",
hab:"Forêt tropicale humide",rep:"Nord de Sumatra",taille:"1,2 à 1,5 m",poidsKg:60,vit:null,vie:45,
reg:"Frugivore",uicn:"CR",rar:5,
res:"Le seul grand singe d'Asie, et le plus grand mammifère arboricole du monde. Son nom signifie « homme de la forêt » en malais.",
f:[["Les mâles adultes existent en deux versions : « à flanges », avec de larges bajoues et un cri qui porte à 1 km, ou « sans flanges », plus petits, qui peuvent le rester des années. Un mâle sans flanges peut se développer d'un coup si le dominant disparaît.","expert"],
["Différentes populations ont des cultures d'outils différentes : bâtons pour extraire les graines de neesia, feuilles en gant, feuilles en mégaphone pour amplifier leurs cris. Ces techniques ne sont pas connues des populations voisines — c'est de la culture, transmise et locale.","expert"],
["Une femelle a un petit tous les 7 à 9 ans, l'intervalle le plus long de tous les mammifères. C'est ce qui rend l'espèce si fragile face à la déforestation.","pointu"],
["En 2017, une troisième espèce d'orang-outan a été décrite : le Pongo tapanuliensis, avec moins de 800 individus. C'est le grand singe le plus menacé du monde.","pointu"]],
v:[["Culture animale","Comportements appris et transmis socialement, qui varient d'un groupe à l'autre sans différence génétique. Attestée chez les orangs-outans, les chimpanzés, les orques et plusieurs oiseaux."]],
q:[["Quel intervalle sépare deux naissances chez la femelle orang-outan ?",["1 an","3 ans","7 à 9 ans","15 ans"],2,"Le plus long de tous les mammifères — d'où la fragilité de l'espèce."],
["Que sont les « flanges » d'un mâle orang-outan ?",["Ses canines","De larges bajoues latérales","Des poils dorsaux","Ses cals fessiers"],1,"Elles marquent le statut de dominant, et peuvent apparaître tardivement."]],
d:["outils","records"]},

{id:"bonobo",nom:"Bonobo",sci:"Pan paniscus",emo:"🐒",gr:"Mammifère",ord:"Primates",fam:"Hominidés",bio:"jungle",
hab:"Forêt humide",rep:"Sud du fleuve Congo (RDC)",taille:"70 à 85 cm",poidsKg:40,vit:null,vie:40,
reg:"Omnivore",uicn:"EN",rar:5,
res:"Avec le chimpanzé, notre plus proche parent vivant. Deux espèces presque identiques génétiquement, et deux sociétés opposées.",
f:[["Bonobos et chimpanzés partagent environ 98,7 % de notre ADN. Ils se sont séparés l'un de l'autre il y a un à deux millions d'années, quand le fleuve Congo s'est formé : les bonobos sont restés au sud, les chimpanzés au nord. Aucun des deux ne sait nager.","expert"],
["Chez les chimpanzés, les mâles dominent et les groupes voisins se font la guerre, parfois mortellement. Chez les bonobos, ce sont les femelles alliées qui dominent, et les rencontres entre groupes se règlent le plus souvent par des contacts sexuels plutôt que par la violence.","pointu"],
["Le sexe y est un outil social : il apaise les tensions, scelle les réconciliations et le partage de nourriture, indépendamment de la reproduction.","pointu"],
["Une hypothèse répandue : au sud du Congo, les bonobos n'ont pas de gorilles comme concurrents pour la nourriture au sol. Une ressource abondante rend la compétition moins nécessaire, et donc la coopération plus payante.","expert"]],
v:[["Spéciation allopatrique","Formation de deux espèces à partir d'une seule, séparée par une barrière géographique — ici un fleuve. Sans échange génétique, les deux populations divergent."]],
q:[["Qu'est-ce qui a séparé bonobos et chimpanzés ?",["Une glaciation","La formation du fleuve Congo","Un volcan","La chasse humaine"],1,"Aucun des deux ne nage : le fleuve est une frontière infranchissable."],
["Comment est organisée une société de bonobos ?",["Par des mâles dominants","Par des femelles alliées","Sans hiérarchie","Par couples isolés"],1,"Les coalitions de femelles tiennent le groupe, à l'inverse des chimpanzés."]],
d:["taxo"]},

{id:"gorille-montagne",nom:"Gorille des montagnes",sci:"Gorilla beringei beringei",emo:"🦍",gr:"Mammifère",ord:"Primates",fam:"Hominidés",bio:"montagne",
hab:"Forêts d'altitude, 2 200 à 4 300 m",rep:"Virunga et Bwindi (RDC, Rwanda, Ouganda)",taille:"1,5 à 1,8 m",poidsKg:160,vit:40,vie:40,
reg:"Herbivore",uicn:"EN",rar:5,
res:"Le plus grand primate du monde, presque entièrement herbivore. Et l'un des rares grands mammifères dont la population remonte.",
f:[["Un mâle adulte pèse jusqu'à 200 kg en ne mangeant quasiment que des tiges, des feuilles et des pousses. Sa force vient d'un microbiote intestinal capable de fermenter la cellulose.","base"],
["Le « dos argenté » n'est pas un titre mais un signe d'âge : les poils du dos blanchissent vers 12 ans, comme des cheveux gris.","base"],
["Chaque gorille construit un nid neuf chaque soir, au sol ou dans un arbre. Les chercheurs comptent les nids pour recenser les populations.","pointu"],
["Ils étaient environ 250 dans les années 1980. Ils sont plus de 1 000 aujourd'hui — le seul grand singe dont la population augmente. En 2018, l'UICN l'a reclassé de « en danger critique » à « en danger ».","expert"],
["Le tambourinage sur la poitrine se fait mains creusées, pas poings fermés : le son creux porte plus loin en forêt, et sa fréquence renseigne sur la taille du mâle. Il ment difficilement.","expert"]],
v:[["Microbiote","Ensemble des micro-organismes qui vivent dans un organisme. Chez les herbivores, ce sont eux qui digèrent la cellulose : l'animal ne fait qu'héberger l'usine."]],
q:[["Que signifie le dos argenté d'un gorille mâle ?",["Sa dominance officielle","Son âge : les poils blanchissent vers 12 ans","Sa sous-espèce","Une maladie"],1,"C'est de la grisonnance, pas un grade — même si les silverbacks dominent souvent."],
["Comment un gorille tambourine-t-il ?",["Poings fermés","Mains creusées","Avec les avant-bras","Avec les pieds"],1,"Mains en coupe : le son creux porte plus loin et trahit la taille de l'animal."]],
d:["retour"]}

]);
